solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <vector>

struct Patch { std::size_t offset; std::vector<std::uint8_t> original; std::vector<std::uint8_t> replacement; };

static bool swapBytes(std::vector<std::uint8_t>& code, std::size_t offset, const std::vector<std::uint8_t>& expect, const std::vector<std::uint8_t>& write)
{
    if (expect.size() != write.size() || offset > code.size() || code.size() - offset < expect.size()) return false;
    if (!std::equal(expect.begin(), expect.end(), code.begin() + static_cast<std::ptrdiff_t>(offset))) return false;
    std::copy(write.begin(), write.end(), code.begin() + static_cast<std::ptrdiff_t>(offset));
    return true;
}

bool apply(std::vector<std::uint8_t>& code, const Patch& p) { return swapBytes(code, p.offset, p.original, p.replacement); }
bool revert(std::vector<std::uint8_t>& code, const Patch& p) { return swapBytes(code, p.offset, p.replacement, p.original); }

static std::vector<std::uint8_t> slice(const std::vector<std::uint8_t>& code, std::size_t offset, std::size_t n)
{
    return { code.begin() + static_cast<std::ptrdiff_t>(offset), code.begin() + static_cast<std::ptrdiff_t>(offset + n) };
}

std::optional<Patch> forceJump(const std::vector<std::uint8_t>& code, std::size_t offset)
{
    if (offset + 2 <= code.size() && code[offset] >= 0x70 && code[offset] <= 0x7F)
        return Patch{ offset, slice(code, offset, 2), { 0xEB, code[offset + 1] } };
    if (offset + 6 <= code.size() && code[offset] == 0x0F && code[offset + 1] >= 0x80 && code[offset + 1] <= 0x8F)
        return Patch{ offset, slice(code, offset, 6), { 0x90, 0xE9, code[offset + 2], code[offset + 3], code[offset + 4], code[offset + 5] } };
    return std::nullopt;
}

std::optional<Patch> invertJump(const std::vector<std::uint8_t>& code, std::size_t offset)
{
    if (offset + 2 <= code.size() && code[offset] >= 0x70 && code[offset] <= 0x7F)
        return Patch{ offset, slice(code, offset, 1), { static_cast<std::uint8_t>(code[offset] ^ 1) } };
    if (offset + 6 <= code.size() && code[offset] == 0x0F && code[offset + 1] >= 0x80 && code[offset + 1] <= 0x8F)
        return Patch{ offset, slice(code, offset, 2), { 0x0F, static_cast<std::uint8_t>(code[offset + 1] ^ 1) } };
    return std::nullopt;
}

Patch nopOut(const std::vector<std::uint8_t>& code, std::size_t offset, std::size_t length)
{
    const std::size_t n{ offset < code.size() ? std::min(length, code.size() - offset) : 0 };
    return { offset, offset < code.size() ? slice(code, offset, n) : std::vector<std::uint8_t>{}, std::vector<std::uint8_t>(n, 0x90) };
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
// call; test al, al; je +0C; ...; 0F 85 near jne; ret
static Bytes code() { return { 0xE8, 0x10, 0x00, 0x00, 0x00, 0x84, 0xC0, 0x74, 0x0C, 0x48, 0x8D, 0x0D, 0x0F, 0x85, 0x20, 0x01, 0x00, 0x00, 0xC3 }; }

TEST("apply and revert check the bytes") {
    Bytes c{ code() };
    const Patch p{ 7, { 0x74, 0x0C }, { 0xEB, 0x0C } };
    CHECK(apply(c, p));
    CHECK_EQ(c[7], 0xEB);
    CHECK(!apply(c, p));
    CHECK(revert(c, p));
    CHECK(c == code());
    CHECK(!revert(c, p));
    CHECK(!apply(c, Patch{ 7, { 0x75, 0x0C }, { 0xEB, 0x0C } }));
    CHECK(!apply(c, Patch{ 18, { 0xC3, 0x00 }, { 0x90, 0x90 } }));
    CHECK(!apply(c, Patch{ 7, { 0x74 }, { 0xEB, 0x0C } }));
}
TEST("forcing jumps") {
    Bytes c{ code() };
    const auto shortJump{ forceJump(c, 7) };
    CHECK(shortJump.has_value());
    if (shortJump) { CHECK(shortJump->replacement == (Bytes{ 0xEB, 0x0C })); CHECK(apply(c, *shortJump)); }
    const auto nearJump{ forceJump(c, 12) };
    CHECK(nearJump.has_value());
    if (nearJump) { CHECK(nearJump->replacement == (Bytes{ 0x90, 0xE9, 0x20, 0x01, 0x00, 0x00 })); CHECK(nearJump->original.size() == 6u); }
    CHECK(!forceJump(c, 0).has_value());
    CHECK(!forceJump(c, 18).has_value());
}
TEST("inverting conditions") {
    Bytes c{ code() };
    const auto a{ invertJump(c, 7) };
    CHECK(a.has_value());
    if (a) { CHECK(apply(c, *a)); CHECK_EQ(c[7], 0x75); }
    const auto b{ invertJump(c, 12) };
    if (b) { CHECK(apply(c, *b)); CHECK_EQ(c[13], 0x84); }
    CHECK(b.has_value());
    CHECK(!invertJump(c, 5).has_value());
}
TEST("nops") {
    Bytes c{ code() };
    const Patch n{ nopOut(c, 5, 4) };
    CHECK(n.original == (Bytes{ 0x84, 0xC0, 0x74, 0x0C }));
    CHECK(apply(c, n));
    CHECK(c[5] == 0x90 && c[8] == 0x90);
    CHECK(revert(c, n));
    CHECK(c == code());
}

